//! The typed operations' hand-written half (spec/typed-sidecar-operations).
//!
//! `operations.rs` is generated by meridian-design, one method per operation,
//! and each calls into this: read the plugin's params as the domain message,
//! stamp what only the sidecar knows, check the grant, send. This is the part
//! that does not vary by operation, which is why it is written once and the
//! part that does is generated.
//!
//! A refusal is the call's gRPC status, chosen by what the caller should do
//! about it: `permission_denied` for a topic none of the plugin's roles
//! grants, `failed_precondition` for an external account nobody has linked,
//! `unavailable` when nothing serves the topic, `deadline_exceeded` when it
//! did not answer in time, `aborted` when it answered with a refusal.

use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use meridian_bus::BusError;
use meridian_domain::v1::{PluginConfiguration, PluginConfigurationRequest};
use meridian_pb::plugin::v1 as plugin;
use meridian_pb::v1::CallerAssertion;
use prost::Message;
use tokio::sync::Mutex;
use tonic::{Response, Status};

use crate::service::Sidecar;

pub const PLUGIN_CONFIGURATION: &str = "platform.config.query.plugin-configuration";
pub const PLUGIN_CONFIGURATION_CHANGED: &str = "platform.config.event.plugin-configuration-changed";

/// External account to account, for this sidecar's plugin, once read; and
/// whether the watch that forgets them on a change has started.
#[derive(Clone, Default)]
pub struct Links {
    held: Arc<Mutex<Option<HashMap<String, String>>>>,
    watching: Arc<AtomicBool>,
}

// The tonic surface already returns `Result<_, Status>` everywhere; boxing the
// error here alone would buy nothing.
#[allow(clippy::result_large_err)]
impl Sidecar {
    pub(crate) fn instance_id(&self) -> &str {
        &self.identity.instance_id
    }

    /// A plugin's params, read as the domain message they are on the wire.
    ///
    /// The params keep every field number of the domain message and drop only
    /// the stamped ones, so their encoding is the domain message's with those
    /// unset. Refused before registration, as every operation is.
    pub(crate) fn as_domain<P: Message, D: Message + Default>(
        &self,
        params: P,
    ) -> Result<D, Status> {
        self.admitted()?;
        D::decode(params.encode_to_vec().as_slice()).map_err(|failed| {
            Status::internal(format!(
                "the params did not read as the domain message: {failed}"
            ))
        })
    }

    /// The topic this instance sends on: its own identifier where the row
    /// names `{instance}`, so a plugin can speak only as itself.
    fn own_topic(&self, topic: &str) -> String {
        topic.replace("{instance}", self.instance_id())
    }

    fn granted(&self, topic: &str) -> Result<(), Status> {
        let registration = self.admitted()?;
        if registration.grants.may_publish(topic) {
            return Ok(());
        }
        let held = if registration.roles.is_empty() {
            "no role".to_string()
        } else {
            registration.roles.join(", ")
        };
        let refusal = format!("no grant for {topic}: this plugin holds {held}");
        self.note_refusal(&refusal);
        Err(Status::permission_denied(refusal))
    }

    /// An event: checked, published, and its identifier handed back.
    pub(crate) async fn publish_typed<D: Message>(
        &self,
        topic: &str,
        payload_type: &str,
        message: D,
    ) -> Result<Response<plugin::Published>, Status> {
        let topic = self.own_topic(topic);
        self.granted(&topic)?;
        let message_id = self
            .bus
            .publish(&topic, payload_type, message.encode_to_vec(), None, None)
            .map_err(refused)?;
        Ok(Response::new(plugin::Published { message_id }))
    }

    /// A command or a query: checked, asked, and the domain reply handed back
    /// as its plugin-facing mirror, which it is on the wire.
    pub(crate) async fn call_typed<D: Message, R: Message + Default>(
        &self,
        topic: &str,
        payload_type: &str,
        message: D,
    ) -> Result<Response<R>, Status> {
        let topic = self.own_topic(topic);
        self.granted(&topic)?;
        let (_, payload) = self
            .bus
            .call(&topic, payload_type, message.encode_to_vec(), None, None)
            .await
            .map_err(refused)?;
        R::decode(payload.as_slice())
            .map(Response::new)
            .map_err(|failed| {
                Status::internal(format!("the reply did not read as its mirror: {failed}"))
            })
    }

    /// A command: checked against the grant, against the plugin's write scope
    /// for the account it names, and -- when it is sent for a person (W4.9) --
    /// against what the dashboard vouched that person may write; then asked,
    /// with the person stamped on the envelope.
    pub(crate) async fn command_typed<D: Message, R: Message + Default>(
        &self,
        topic: &str,
        payload_type: &str,
        message: D,
        account: Option<String>,
        acting_for: Option<CallerAssertion>,
    ) -> Result<Response<R>, Status> {
        let topic = self.own_topic(topic);
        self.granted(&topic)?;
        let now = now_ns();
        if let Some(account) = &account {
            if !self.write_scope(now).await?.contains(account) {
                let refusal = format!(
                    "account {account} is outside this plugin's write scope: nobody may write \
                     it through this plugin"
                );
                self.note_refusal(&refusal);
                return Err(Status::permission_denied(refusal));
            }
        }
        let subject = match acting_for {
            None => String::new(),
            Some(assertion) => self.vouched_writer(&assertion, account.as_deref(), now)?,
        };
        let (_, payload) = self
            .bus
            .call_for(
                &topic,
                payload_type,
                message.encode_to_vec(),
                None,
                None,
                &subject,
            )
            .await
            .map_err(refused)?;
        R::decode(payload.as_slice())
            .map(Response::new)
            .map_err(|failed| {
                Status::internal(format!("the reply did not read as its mirror: {failed}"))
            })
    }

    /// The person an assertion vouches for, if they may write `account`
    /// through this plugin -- or, for a command naming none, anything at all
    /// through it. Their access is what the dashboard signed, under a minute
    /// ago; a person narrows what a plugin may do and never widens it.
    fn vouched_writer(
        &self,
        assertion: &CallerAssertion,
        account: Option<&str>,
        now_ns: i64,
    ) -> Result<String, Status> {
        let verifier = self.verifier.as_ref().ok_or_else(|| {
            Status::unauthenticated(
                "this sidecar holds none of the dashboard's keys, so it can vouch for nobody",
            )
        })?;
        let claims = verifier
            .vouched(assertion, now_ns)
            .map_err(|refusal| Status::unauthenticated(refusal.said()))?;
        let may_write = crate::scope::writes(&claims.access);
        match account {
            Some(account) if !may_write.contains(account) => Err(Status::permission_denied(
                format!("the person may not write account {account} through this plugin"),
            )),
            None if may_write.is_empty() => Err(Status::permission_denied(
                "the person may write nothing through this plugin",
            )),
            _ => Ok(claims.subject),
        }
    }

    /// The account an external account is linked to (W6.4), or the refusal
    /// that names what to do: a row for an unlinked account is refused, not
    /// guessed at, and recorded once somebody links it.
    pub(crate) async fn linked_account(&self, external_account_id: &str) -> Result<String, Status> {
        if external_account_id.is_empty() {
            return Err(Status::invalid_argument(
                "external_account_id is required: the account as the rail knows it",
            ));
        }
        let links = self.links().await?;
        links.get(external_account_id).cloned().ok_or_else(|| {
            Status::failed_precondition(format!(
                "external account {external_account_id} is not linked to an account; a \
                 deployment admin links it (W6.4), and the next statement records it"
            ))
        })
    }

    /// This plugin's links, from the conductor the first time and after each
    /// change it announces. Asked as this instance, since the conductor
    /// answers for the instance the envelope names.
    async fn links(&self) -> Result<HashMap<String, String>, Status> {
        // Watching before reading, so a change that lands between the two is
        // not missed; and once, however often the links are read again.
        if !self.links.watching.swap(true, Ordering::SeqCst) {
            self.forget_links_on_change();
        }
        let mut held = self.links.held.lock().await;
        if let Some(links) = held.as_ref() {
            return Ok(links.clone());
        }
        let (_, payload) = self
            .bus
            .call(
                PLUGIN_CONFIGURATION,
                "meridian.v1.PluginConfigurationRequest",
                PluginConfigurationRequest {}.encode_to_vec(),
                None,
                None,
            )
            .await
            .map_err(refused)?;
        let configuration = PluginConfiguration::decode(payload.as_slice()).map_err(|failed| {
            Status::internal(format!(
                "the plugin's configuration did not decode: {failed}"
            ))
        })?;
        let links: HashMap<String, String> = configuration
            .links
            .into_iter()
            .filter(|link| link.plugin_instance_id == self.instance_id())
            .map(|link| (link.external_account_id, link.account_id))
            .collect();
        *held = Some(links.clone());
        Ok(links)
    }

    /// Forget the links whenever the conductor says this plugin's
    /// configuration changed, so the next operation reads them afresh.
    fn forget_links_on_change(&self) {
        let mut changes = self.bus.subscribe(PLUGIN_CONFIGURATION_CHANGED);
        let links = self.links.clone();
        let instance = self.instance_id().to_string();
        tokio::spawn(async move {
            while let Some(delivery) = changes.recv().await {
                let changed = meridian_domain::v1::PluginConfigurationChangedEvent::decode(
                    &delivery.envelope.payload[..],
                );
                if matches!(changed, Ok(event) if event.plugin_instance_id == instance) {
                    *links.held.lock().await = None;
                }
            }
        });
    }
}

fn now_ns() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as i64)
        .unwrap_or(0)
}

fn refused(failed: BusError) -> Status {
    match failed {
        BusError::NoHandler(topic) => Status::unavailable(format!("nothing serves {topic}")),
        timeout @ BusError::Timeout { .. } => Status::deadline_exceeded(timeout.to_string()),
        BusError::HandlerFailed { detail, .. } => Status::aborted(detail),
        BusError::NotPublishable(topic) => {
            Status::invalid_argument(format!("`{topic}` is not a publishable topic"))
        }
        other => Status::internal(other.to_string()),
    }
}

